    # ---- parameters -----------------------------------------------------------------
    S.append('    <h3 id="s1-params">Parameters — per patient</h3>')
    S.append('    ' + ul(
        "columns: crop = EL / HUG preset <code>time_range</code> (MicroEPI: preset) · ref = reference route, WM contact count · bad = <code>bad_channels_manual</code> entries · unk = Unknown-parcellation drops · notch = method (· shaft = per-shaft) · trials = used per condition (after accuracy / duration / IQR) · cubes = per condition",
        "source: <code>audit_140.tsv</code>; a rerun changes this table on the next <code>make_s1_tab.py --insert</code>",
    ))
    S.append('    ' + (patient_table(a) if a is not None else "<p>audit table missing</p>"))

    # ---- outputs -------------------------------------------------------------------
    S.append('    <h3 id="s1-outputs">Outputs — where things are</h3>')
